(908, 1, '2025-03-11 21:46:25', '2025-03-11 20:46:25', '<!-- wp:um-block/um-account {\"tab\":\"all\"} /-->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:shortcode -->\n[lien_admin_auteur]\n<!-- /wp:shortcode -->\n\n<!-- wp:navigation {\"ref\":428} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/DicoTrav/index.php/logout\">Se déconnecter</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n\n<!-- wp:html -->\n<style>\n/* Texte par défaut pour le reste de la page */\nbody {\n  color: #15070F;\n}\n\n/* Style pour le lien actif du compte */\n.um-account-link.current {\n  background-color: #29354C;\n  color: #F7F1EB;\n  padding: 0.5em 1em;\n  transition: background-color 0.3s;\n}\n\n/* Style pour les boutons */\n.um-button {\n  background-color: #29354C;\n  color: #F7F1EB;\n  border: none;\n  padding: 0.5em 1em;\n  transition: background-color 0.3s;\n}\n\n/* Effet hover pour le lien actif et les boutons */\n.um-account-link.current:hover,\n.um-button:hover {\n  background-color: #3c5075;\n}\n</style>\n\n<!-- /wp:html -->', 'Compte', '', 'inherit', 'closed', 'closed', '', '592-revision-v1', '', '', '2025-03-11 21:46:25', '2025-03-11 20:46:25', '', 592, 'http://localhost/DicoTrav/?p=908', 0, 'revision', '', 0),
(907, 1, '2025-03-11 21:43:50', '2025-03-11 20:43:50', '<!-- wp:um-block/um-account {\"tab\":\"all\"} /-->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:shortcode -->\n[lien_admin_auteur]\n<!-- /wp:shortcode -->\n\n<!-- wp:navigation {\"ref\":428} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/DicoTrav/index.php/logout\">Se déconnecter</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n\n<!-- wp:html -->\n<style>\n/* Texte par défaut pour le reste de la page */\nbody {\n  color: #15070F;\n}\n\n/* Sections du profil : fond et texte */\n.um-account,\n.um-account-meta,\n.um-account-main,\n.um-account-tab,\n.um-field {\n  background-color: #29354C;\n  color: #F7F1EB;\n  padding: 1em; /* facultatif, pour espacer un peu */\n  margin-bottom: 1em;\n}\n\n/* Boutons : fond et texte */\n.um-button,\n.wp-block-button__link {\n  background-color: #29354C;\n  color: #F7F1EB;\n  border: none;\n  padding: 0.5em 1em;\n  text-decoration: none;\n  transition: background-color 0.3s;\n}\n\n/* Effet hover pour sections et boutons */\n.um-account:hover,\n.um-account-meta:hover,\n.um-account-main:hover,\n.um-account-tab:hover,\n.um-field:hover,\n.um-button:hover,\n.wp-block-button__link:hover {\n  background-color: #3c5075;\n}\n\n/* Liens à l\'intérieur des sections du profil */\n.um-account a,\n.um-account-meta a,\n.um-account-main a,\n.um-account-tab a,\n.um-field a {\n  color: #F7F1EB;\n}\n</style>\n<!-- /wp:html -->', 'Compte', '', 'inherit', 'closed', 'closed', '', '592-revision-v1', '', '', '2025-03-11 21:43:50', '2025-03-11 20:43:50', '', 592, 'http://localhost/DicoTrav/?p=907', 0, 'revision', '', 0),
