g\\u0022:\\u00220px\\u0022,\\u0022containerBorderStyle\\u0022:\\u0022none\\u0022,\\u0022containerBorderWidth\\u0022:\\u00221px\\u0022,\\u0022containerBorderColor\\u0022:\\u0022#000000\\u0022,\\u0022containerBorderRadius\\u0022:\\u00223px\\u0022,\\u0022containerShadowSize\\u0022:\\u0022none\\u0022,\\u0022customCss\\u0022:\\u0022.form-contact form{\\\\ndisplay:flex;\\\\nflex-direction:column;\\\\nalign-items:center;\\\\njustify-content:center;\\\\n}\\\\n.form-newletters .wpforms-field {\\\\ndisplay:inline-flex;\\\\nalign-items:center;\\\\n}\\\\n\\\\n.form-contact form .wpforms-field-label{\\\\nmargin-left: 0 !important;\\\\n}\\\\n\\\\n.form-contact form input{\\\\nmin-width:100%;\\\\n}\\\\n\\\\n.form-contact .wpforms-field .wpforms-field-label{\\\\nmargin:10px;\\\\ncolor:#3A2A1D;\\\\n}\\\\n\\\\n.btn-contact{\\\\nmargin : auto;\\\\n}\\u0022}\",\"fieldBackgroundColor\":\"#f7f1eb\",\"fieldBorderColor\":\"#29354c\",\"fieldTextColor\":\"#29354c\",\"fieldMenuColor\":\"#29354c\",\"buttonBackgroundColor\":\"#15070f\",\"buttonTextColor\":\"#f7f1eb\"} /-->\n\n<!-- wp:html -->\n<style>\n/* Style global du formulaire */\n.form-contact {\n    max-width: 600px;\n    margin: 0 auto;\n    padding: 20px;\n    background: #f9f9f9;\n    border-radius: 8px;\n    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);\n}\n\n/* Style des champs */\n.wpforms-field-container {\n    display: flex;\n    flex-direction: column;\n    gap: 15px;\n}\n\n/* Labels */\n.wpforms-field-label {\n    font-weight: 600;\n    color: #333;\n    margin-bottom: 5px;\n    display: block;\n}\n\n/* Inputs et Textarea */\n.wpforms-field input,\n.wpforms-field textarea {\n    width: 100%;\n    padding: 12px;\n    border: 1px solid #ccc;\n    border-radius: 5px;\n    font-size: 16px;\n    transition: border-color 0.3s ease;\n}\n\n.wpforms-field input:focus,\n.wpforms-field textarea:focus {\n    border-color: #0073e6;\n    outline: none;\n}\n\n/* Textarea spécifique */\n.wpforms-field textarea {\n    min-height: 120px;\n    resize: vertical;\n}\n\n/* Style des champs requis */\n.wpforms-required-label {\n    color: red;\n}\n\n/* Champ caché (protection antispam) */\n#wpforms-376-field_1-container {\n    display: none !important;\n}\n\n/* Bouton déjà stylisé, donc non modifié ici */\n\n</style>\n<!-- /wp:html --></div>\n<!-- /wp:group -->', 'Nous contacter', '', 'inherit', 'closed', 'closed', '', '134-revision-v1', '', '', '2025-03-31 02:21:08', '2025-03-31 00:21:08', '', 134, 'http://localhost/DicoTrav/?p=1372', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1375, 1, '2025-03-31 02:41:33', '2025-03-31 00:41:33', '{\"styles\":{\"elements\":{\"heading\":{\"typography\":{\"lineHeight\":\"0.5\",\"fontFamily\":\"var(--wp--preset--font-family--eb-garamond)\"},\"color\":{\"text\":\"var(--wp--preset--color--custom-brown)\"}},\"link\":{\"typography\":{\"fontFamily\":\"var(--wp--preset--font-family--roboto)\",\"fontSize\":\"var(--wp--preset--font-size--small)\"},\"color\":{\"text\":\"var(--wp--preset--color--custom-brown)\"},\":hover\":{\"color\":{\"text\":\"var(--wp--preset--color--custom-red)\"}}},\"caption\":{\"color\":{\"text\":\"var(--wp--preset--color--custom-brown)\"},\"typography\":{\"fontFamily\":\"var(--wp--preset--font-family--roboto)\"}},\"button\":{\"color\":{\"text\":\"var(--wp--preset--color--custom-light-pink)\",\"background\":\"var(--wp--preset--color--custom-mid-brown)\"},\"typography\":{\"fontFamily\":\"var(--wp--preset--font-family--roboto)\"}},\"h1\":{\"typography\":{\"fontFamily\":\"var(--wp--preset--font-family--eb-garamond)\"}},\"h2\":{\"typography\":{\"fontFamily\":\"var(--wp--preset--font-family--eb-garamond)\"}},\"h3\":{\"typography\":{\"fontFamily\":\"var(--wp--preset--font-family--eb-garamond)\"}},\"h4\":{\"typography\":{\"fontFamily\":\"var(--wp--preset--font-family--eb-garamond)\"}}},\"color\":{\"text\":\"var(--wp--preset--color--custom-brown)\",\"background\":\"var(--wp--preset--color--custom-light-pink)\"},\"typography\":{\"fontFamily\":\"var(--wp--preset--font-family--roboto)\",\"fontSize\":\"var(--wp--preset--font-size--small)\"},\"css\":\"\\/* ===================== *\\/\\n\\/*      Base & R\\u00e9initialisations      *\\/\\n\\/* ===================== *\\/\\n\\n.wp-site-blocks {\\n    padding: 0;\\n  }\\n  \\n  :where(.wp-site-blocks) > * {\\n    margin-block-start: 0;\\n    margin-block-end: 0;\\n  }\\n  \\n  \\/* ===================== *\\/\\n  \\/*         Liens & Hover         *\\/\\n  \\/* ===================== *\\/\\n  \\n  .Account-link a {\\n    color: #F7F1EB !important;\\n    text-decoration: none;\\n    display: inline-block;\\n    transition: transform 0.2s ease, color 0.2s ease;\\n    will-change: transform;\\n  }\\n  .Account-link a:hover {\\n    text-decoration: underline;\\n    transform: scale(1.05);\\n    color: #D4A373 !important;\\n  }\\n  \\n  .links-dark,\\n  .links-dark-underline {\\n    color: #29354C !important;\\n    text-decoration: none;\\n    display: inline-block;\\n    transition: transform 0.2s ease, color 0.2s ease;\\n    will-change: transform;\\n  }\\n  .links-dark-underline {\\n    text-decoration: underline;\\n  }\\n  .links-dark:hover {\\n    text-decoration: underline;\\n    transform: scale(1.05);\\n    color: #D4A373 !important;\\n  }\\n  .links-dark-underline:hover {\\n    text-decoration: none;\\n    transform: scale(1.05);\\n    color: #D4A373 !important;\\n  }\\n  \\n  \\/* ===================== *\\/\\n  \\/*          Main & Layout Global         *\\/\\n  \\/* ===================== *\\/\\n  \\n  main {\\n    transition: margin-left 0.3s ease !important, width 0.3s ease !important;\\n    box-sizing: border-box !important;\\n    padding-top: 234px !important;\\n  }\\n  \\n  \\/* Affichage mobile par d\\u00e9faut *\\/\\n  .mobile {\\n    display: flex !important;\\n  }\\n  .desktop {\\n    display: none !important;\\n  }\\n  \\n  \\/* ===================== *\\/\\n  \\/*         Desktop (>=768px)         *\\/\\n  \\/* ===================== *\\/\\n  \\n  @media screen and (min-width: 768px) {\\n    main {\\n      margin-left: 250px !important;\\n      width: calc(100% - 250px) !important;\\n      min-height: 100vh;\\n      padding-top: 134px !important;\\n    }\\n    \\n    header {\\n      z-index: 100 !important;\\n    }\\n    \\n    .mobile {\\n      display: none !important;\\n    }\\n    .desktop {\\n      display: flex !important;\\n      flex-direction: row !important;\\n      justify-content: space-between !important;\\n    }\\n    \\n    .search-focus {\\n      margin-right: 64px !important;\\n    }\\n  }\\n  \\n  \\/* ===================== *\\/\\n  \\/*             Header             *\\/\\n  \\/* ===================== *\\/\\n  \\n  Header {\\n    position: fixed;\\n    min-width: 100%;\\n    z-index: 200;\\n    margin-bottom: 134px !important;\\n  }\\n  \\n  .header-top {\\n    max-height: 86px !important;\\n    display: flex;\\n    flex-wrap: wrap;\\n    align-items: center;\\n    justify-content: space-between;\\n    padding: var(--wp--preset--spacing--10);\\n  }\\n  \\n  \\/* ===================== *\\/\\n  \\/*           Footer & Images           *\\/\\n  \\/* ===================== *\\/\\n  \\n  Footer {\\n    position: relative;\\n    z-index: 100 !important;\\n  }\\n  \\n  .img-round,\\n  .wp-image-236 {\\n    border-radius: 10px !important;\\n  }\\n  \\n  \\/* ===================== *\\/\\n  \\/*        Profil & Logo         *\\/\\n  \\/* ===================== *\\/\\n  \\n  .Logo-site-img {\\n    border-radius: 50% !important;\\n  }\\n  \\n  .Header-Text,\\n  .Header-Logo-Text {\\n    color: #F7F1EB !important;\\n    text-decoration: none;\\n    display: inline-block;\\n  }\\n  \\n  .profile-logo-link {\\n    display: inline-flex !important;\\n    align-items: center !important;\\n    justify-content: center !important;\\n    text-decoration: none !important;\\n  }\\n  .profile-logo-link img {\\n    border-radius: 50% !important;\\n    width: 50px !important;\\n    height: 50px !important;\\n    transition: transform 0.2s ease !important;\\n    display: block !important;\\n  }\\n  .profile-logo-link:hover img {\\n    transform: scale(1.05) !important;\\n  }\\n  \\n  \\/* ===================== *\\/\\n  \\/*      Recherche (Search)      *\\/\\n  \\/* ===================== *\\/\\n  \\n  .wp-block-search__inside-wrapper {\\n    width: 100%;\\n    max-width: 300px;\\n    margin: 0 auto;\\n  }\\n  \\n  .wp-block-search__input {\\n    transition: all 0.3s ease-in-out;\\n    border-radius: 10px;\\n    padding: 10px;\\n    border: 2px solid transparent;\\n    outline: none;\\n    width: 100%;\\n    max-width: 300px;\\n  }\\n  .wp-block-search__input:focus {\\n    width: 350px;\\n    max-width: 350px;\\n    border-color: #D4A373;\\n    box-shadow: 0 0 12px rgba(212, 163, 115, 0.8);\\n  }\\n  \\n  .wp-block-search__button {\\n    background-color: #D4A373;\\n    border-radius: 50%;\\n    padding: 15px;\\n    border: none;\\n    transition: transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out;\\n  }\\n  .wp-block-search__button:hover {\\n    transform: scale(1.1);\\n    box-shadow: 0 0 8px rgba(212, 163, 115, 0.8);\\n  }\\n  .wp-block-search__button svg {\\n    transition: transform 0.2s ease-in-out;\\n    fill: #F7F1EB;\\n  }\\n  .wp-block-search__input:focus + .wp-block-search__button svg {\\n    transform: rotate(15deg);\\n  }\\n  \\n  \\/* ===================== *\\/\\n  \\/*      Traduction (TRP Floater)      *\\/\\n  \\/* ===================== *\\/\\n  \\n  #trp-floater-ls.trp-bottom-right {\\n    right: 10px !important;\\n    bottom: 10px !important;\\n    border-radius: 5px !important;\\n    background: #29354C !important;\\n    transition: transform 0.2s ease;\\n    cursor: pointer;\\n    z-index: 999;\\n  }\\n  #trp-floater-ls-current-language a {\\n    margin: 10px 0 !important;\\n  }\\n  #trp-floater-ls-language-list .trp-language-wrap a {\\n    margin: 10px !important;\\n  }\\n  #trp-floater-ls.trp-bottom-right:hover {\\n    transform: scale(1.05);\\n  }\\n  #trp-floater-ls a {\\n    color: #F7F1EB;\\n    text-decoration: none;\\n    font-size: 12px;\\n    padding: 3px 5px;\\n    display: inline-block;\\n  }\\n  #trp-floater-ls.trp-floater-ls-codes #trp-floater-ls-language-list {\\n    margin-top: 0 !important;\\n  }\\n  \\n  \\/* ===================== *\\/\\n  \\/*        Responsive (max-width: 768px)        *\\/\\n  \\/* ===================== *\\/\\n  \\n  @media screen and (max-width: 768px) {\\n    \\/* R\\u00e9organisation du conteneur global des ic\\u00f4nes et du formulaire *\\/\\n    .wp-container-core-group-is-layout-17 {\\n      flex-direction: column !important;\\n      align-items: center;\\n      gap: 20px;\\n    }\\n\\n    .wp-container-core-group-is-layout-16 {\\n      flex-wrap: wrap !important;\\n      justify-content: center !important;\\n      align-items: center;\\n    }\\n    \\/* Ic\\u00f4nes de partage en premier *\\/\\n    .wp-container-core-group-is-layout-17 > .wp-block-group.is-layout-flex {\\n      order: 1;\\n      width: 100%;\\n      text-align: center;\\n    }\\n    \\/* Formulaire en deuxi\\u00e8me *\\/\\n    .wp-container-core-group-is-layout-17 > .wpforms-container {\\n      order: 2;\\n      width: 100%;\\n      text-align: center;\\n    }\\n    \\/* Centrage du champ d\'email *\\/\\n    #wpforms-190-field_2 {\\n      margin: 0 auto;\\n      text-align: center;\\n    }\\n\\n    .form-newletters .wpforms-field {\\n        display: inline-flex !important;\\n        align-items: flex-end;\\n    }\\n\\n    .wpforms-field-email{\\n        flex-direction: column !important;\\n        display: flex !important;\\n        align-items: flex-start !important;\\n    }\\n  }\\n  \\n  \\/* ===================== *\\/\\n  \\/*        Formulaire : R\\u00e9duction du padding dans le header du formulaire        *\\/\\n  \\/* ===================== *\\/\\n  \\n  .wpforms-head-container {\\n    padding: 0px !important; \\/* Ajuste selon tes besoins *\\/\\n  }\\n  \\n  .form-newletters .wpforms-field {\\n    display: flex !important;\\n    align-items: flex-end;\\n}\\n\\n.wpforms-submit{\\n    background-color: #3c5075 !important;\\n    color: #F7F1EB !important;\\n    border-radius: 10px;\\n    border: none !important;\\n    transition: background-color 0.3s, color 0.2s !important;\\n    font-weight: bold !important;\\n}\\n  \\n\\/* Effet hover pour le lien actif et les boutons *\\/\\n.wpforms-submit:hover{\\n    background-color: #D4A373 !important;\\n    color: #29354C !important;\\n}\\n\\n.wpforms-field-label {\\n    display: inline-flex !important;\\n    margin-right: 10px !important;\\n}\"},\"settings\":{\"typography\":{\"fontFamilies\":{\"theme\":[],\"custom\":[{\"name\":\"EB Garamond\",\"slug\":\"eb-garamond\",\"fontFamily\":\"\\\"EB Garamond\\\", serif\",\"fontFace\":[{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGDmQSNjdsmc35JDF1K5E55YMjF_7DPuGi-6_RUBoV-e6yHgQ.woff2\",\"fontWeight\":\"400\",\"fontStyle\":\"normal\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGDmQSNjdsmc35JDF1K5E55YMjF_7DPuGi-2fRUBoV-e6yHgQ.woff2\",\"fontWeight\":\"500\",\"fontStyle\":\"normal\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGDmQSNjdsmc35JDF1K5E55YMjF_7DPuGi-NfNUBoV-e6yHgQ.woff2\",\"fontWeight\":\"600\",\"fontStyle\":\"normal\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGDmQSNjdsmc35JDF1K5E55YMjF_7DPuGi-DPNUBoV-e6yHgQ.woff2\",\"fontWeight\":\"700\",\"fontStyle\":\"normal\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGDmQSNjdsmc35JDF1K5E55YMjF_7DPuGi-a_NUBoV-e6yHgQ.woff2\",\"fontWeight\":\"800\",\"fontStyle\":\"normal\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7e8QI9_WamXgXFI.woff2\",\"fontWeight\":\"400\",\"fontStyle\":\"italic\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7eOQI9_WamXgXFI.woff2\",\"fontWeight\":\"500\",\"fontStyle\":\"italic\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7diR49_WamXgXFI.woff2\",\"fontWeight\":\"600\",\"fontStyle\":\"italic\",\"fontFamily\":\"\\\"EB Garamond\\\"