(1021, 'CSS', '', 'easy-table-of-contents', 0, 1021, 0),
(1022, 'Prevent the loading the core CSS styles. When selected, the appearance options from above will be ignored.', 'Empêcher le chargement des styles CSS de base. Lorsque cette option est sélectionnée, les options d’apparence ci-dessus seront ignorées.', 'easy-table-of-contents', 2, 1022, 0),
(1023, 'Inline CSS', 'CSS en ligne', 'easy-table-of-contents', 2, 1023, 0),
(1024, 'Improve your  website performance by inlining your CSS.', 'Améliorez les performances de votre site en mettant en ligne vos CSS.', 'easy-table-of-contents', 2, 1024, 0),
(1025, 'Headings:', 'Titrages :', 'easy-table-of-contents', 2, 1025, 0),
(1026, 'Select the heading to consider when generating the table of contents. Deselecting a heading will exclude it.', 'Sélectionnez le titrage à prendre en compte lors de la génération de la table des matières. Désélectionner un titrage l’exclura.', 'easy-table-of-contents', 2, 1026, 0),
(1027, 'Heading 1 (h1)', 'Titrage 1 (h1)', 'easy-table-of-contents', 2, 1027, 0),
